class Solution {
    public int minimumRecolors(String blocks,int k){
        int white=0;
        for(int i=0;i<k;i++)if(blocks.charAt(i)=='W')white++;
        int answer=white;
        for(int i=k;i<blocks.length();i++){
            if(blocks.charAt(i)=='W')white++;
            if(blocks.charAt(i-k)=='W')white--;
            answer=Math.min(answer,white);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumRecolors(blocks:String,k:Int):Int{
        var white=(0 until k).count{
            blocks[it]=='W'
        };
        var answer=white;
        for(i in k until blocks.length){
            if(blocks[i]=='W')white++;
            if(blocks[i-k]=='W')white--;
            answer=minOf(answer,white)
        };
        return answer
    }
}

